declare(strict_types=1);
session_start();
$loggedIn = !empty($_SESSION['aq_admin']);
?><!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>AQSite Content Backend</title>
  <style>
    :root{--bg:#111318;--panel:#1b1e26;--panel2:#242832;--text:#f4f5f7;--muted:#aab0bd;--accent:#c9a36a;--danger:#d86c6c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 Arial,sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer;border:0;border-radius:6px;padding:9px 14px;background:var(--accent);color:#111;font-weight:700}button.secondary{background:var(--panel2);color:var(--text)}button.danger{background:var(--danger);color:#fff}.wrap{max-width:1400px;margin:auto;padding:30px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:25px}h1,h2,h3{margin-top:0}.muted{color:var(--muted)}.notice{padding:12px 14px;background:#302a1f;border:1px solid #695331;border-radius:6px;margin-bottom:18px}.login{max-width:420px;margin:12vh auto;background:var(--panel);padding:28px;border-radius:10px}.field{display:grid;gap:6px;margin:12px 0}label{color:var(--muted);font-weight:700}input,textarea,select{width:100%;background:#101218;color:var(--text);border:1px solid #3a404c;border-radius:5px;padding:9px}textarea{min-height:110px;resize:vertical}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.tab{background:var(--panel2);color:var(--text)}.tab.active{background:var(--accent);color:#111}.panel{background:var(--panel);border-radius:9px;padding:20px;margin-bottom:18px}.row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;align-items:end}.row .wide{grid-column:span 2}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.card{background:var(--panel2);border-radius:7px;padding:14px;margin:10px 0}.cardgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px}.project-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:9px}.project-fields .field{margin:0}.empty{padding:25px;text-align:center;color:var(--muted)}.hidden{display:none!important}@media(max-width:800px){.row{grid-template-columns:1fr}.row .wide{grid-column:auto}.top{align-items:flex-start;flex-direction:column}}
  </style>
</head>
<body>
<?php if (!$loggedIn): ?>
  <main class="login"><h1>AQSite Backend</h1><p class="muted">Manage services, industries, detail pages, and project collections.</p><div id="loginError" class="notice hidden"></div><form id="loginForm"><div class="field"><label>Username</label><input name="username" value="admin" required></div><div class="field"><label>Password</label><input name="password" type="password" required></div><button>Sign in</button></form></main>
<?php else: ?>
  <main class="wrap"><header class="top"><div><h1>AQSite Backend</h1><div class="muted">Content management only — the website structure is not changed.</div></div><button id="logout" class="secondary">Log out</button></header><div id="message" class="notice hidden"></div>
    <nav class="tabs"><button class="tab active" data-tab="services">Service listings</button><button class="tab" data-tab="collections">Project collections</button><button class="tab" data-tab="details">Detail pages</button></nav>
    <section id="services" class="tabContent"><div class="panel"><h2>Services</h2><p class="muted">Add, edit, or delete the service cards currently read by the website.</p><div id="servicesList"></div><div class="actions"><button id="addService">Add service</button><button id="saveServices">Save service changes</button></div></div></section>
    <section id="collections" class="tabContent hidden"><div class="panel"><h2>Project collections</h2><p class="muted">These are the existing JSON project lists under <code>data/portfolios</code>. Add, edit, or delete project records, then save.</p><div class="field"><label>Collection</label><select id="collectionSelect"></select></div><div id="collectionEditor"></div><div class="actions"><button id="addProject">Add project</button><button id="saveCollection">Save project changes</button></div></div></section>
    <section id="details" class="tabContent hidden"><div class="panel"><h2>Service and industry detail pages</h2><p class="muted">Edit the existing title and description in each detail page. Changes are backed up in <code>Backend/backups</code>.</p><div class="row"><div class="field"><label>Content type</label><select id="detailType"><option value="services">Services</option><option value="industries">Industries</option></select></div><div class="field wide"><label>Detail page</label><select id="detailSelect"></select></div></div><div id="detailEditor"></div><div class="actions"><button id="saveDetail">Save detail page</button></div></div></section>
  </main>
<?php endif; ?>
<script>
const api='api.php';let state=null,currentCollection=null;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function call(action,body){const r=await fetch(`${api}?action=${action}`,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!d.ok)throw Error(d.error||'Request failed');return d}
function message(text,error=false){const e=$('#message');if(!e)return;e.textContent=text;e.classList.remove('hidden');e.style.borderColor=error?'#8d4545':'#695331';setTimeout(()=>e.classList.add('hidden'),4000)}
<?php if (!$loggedIn): ?>
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.target);try{await call('login',Object.fromEntries(form));location.reload()}catch(x){$('#loginError').textContent=x.message;$('#loginError').classList.remove('hidden')}});
<?php else: ?>
async function init(){try{state=await call('bootstrap');renderServices();renderCollections();renderDetails()}catch(x){message(x.message,true)}}
function renderServices(){const root=$('#servicesList');root.innerHTML='';if(!state.services.length){root.innerHTML='<div class="empty">No services found.</div>';return}state.services.forEach((item,i)=>{const card=document.createElement('div');card.className='card service';card.dataset.i=i;card.innerHTML=`<div class="row"><div class="field"><label>Title</label><input data-k="title" value="${esc(item.title)}"></div><div class="field wide"><label>Description</label><textarea data-k="desc">${esc(item.desc)}</textarea></div><div class="field"><label>Image</label><input data-k="img" value="${esc(item.img)}"></div><div class="field"><label>Link</label><input data-k="link" value="${esc(item.link)}"></div></div><div class="actions"><button class="danger removeService">Delete service</button></div>`;root.appendChild(card)})}
function readServices(){return [...document.querySelectorAll('.service')].map(card=>{const item={};card.querySelectorAll('[data-k]').forEach(x=>item[x.dataset.k]=x.value);return item})}
$('#addService').onclick=()=>{state.services.push({title:'New service',img:'',desc:'',link:'/dark/ser-new-service'});renderServices()};$('#servicesList').addEventListener('click',e=>{if(e.target.classList.contains('removeService')){state.services.splice(+e.target.closest('.service').dataset.i,1);renderServices()}});$('#saveServices').onclick=async()=>{try{await call('save-services',{items:readServices()});state.services=readServices();message('Services saved successfully.')}catch(x){message(x.message,true)}};
function renderCollections(){const select=$('#collectionSelect');select.innerHTML=state.collections.map((c,i)=>`<option value="${esc(c.key)}">${esc(c.label)}</option>`).join('');select.onchange=()=>{currentCollection=state.collections.find(c=>c.key===select.value);renderCollectionEditor()};currentCollection=state.collections[0];if(currentCollection){select.value=currentCollection.key;renderCollectionEditor()}}
function fieldsFor(items){const keys=[];items.forEach(x=>{if(x&&typeof x==='object')Object.keys(x).forEach(k=>{if(!keys.includes(k))keys.push(k)})});return keys.length?keys:['value']}
function renderCollectionEditor(){const root=$('#collectionEditor');if(!currentCollection){root.innerHTML='<div class="empty">No collections found.</div>';return}const scalar=typeof currentCollection.items[0]!=='object';const keys=fieldsFor(currentCollection.items);root.innerHTML=currentCollection.items.map((item,i)=>{const values=scalar?{value:item}:item;return `<div class="card project" data-i="${i}"><div class="project-fields">${keys.map(k=>`<div class="field"><label>${esc(k)}</label><input data-k="${esc(k)}" value="${esc(values?.[k])}"></div>`).join('')}</div><div class="actions"><button class="danger removeProject">Delete project</button></div></div>`}).join('')||'<div class="empty">No projects in this collection.</div>'}
function readCollection(){const scalar=typeof currentCollection.items[0]!=='object';return [...document.querySelectorAll('.project')].map(card=>{const o={};card.querySelectorAll('[data-k]').forEach(x=>o[x.dataset.k]=x.value);return scalar?o.value:o})}
$('#collectionSelect').addEventListener('change',e=>{currentCollection=state.collections.find(c=>c.key===e.target.value);renderCollectionEditor()});$('#addProject').onclick=()=>{if(!currentCollection)return;const scalar=typeof currentCollection.items[0]!=='object';currentCollection.items.push(scalar?'':Object.fromEntries(fieldsFor(currentCollection.items).map(k=>[k,''])));renderCollectionEditor()};$('#collectionEditor').addEventListener('click',e=>{if(e.target.classList.contains('removeProject')){currentCollection.items.splice(+e.target.closest('.project').dataset.i,1);renderCollectionEditor()}});$('#saveCollection').onclick=async()=>{try{await call('save-collection',{key:currentCollection.key,items:readCollection()});currentCollection.items=readCollection();message('Project collection saved successfully.')}catch(x){message(x.message,true)}};
function renderDetails(){const type=$('#detailType').value;const group=state.details[type];$('#detailSelect').innerHTML=Object.values(group).map(d=>`<option value="${esc(d.key)}">${esc(d.label)}</option>`).join('');renderDetailEditor()}function renderDetailEditor(){const d=state.details[$('#detailType').value][$('#detailSelect').value];if(!d){$('#detailEditor').innerHTML='';return}$('#detailEditor').innerHTML=`<div class="field"><label>Title</label><input id="detailTitle" value="${esc(d.title)}"></div><div class="field"><label>Description</label><textarea id="detailDescription">${esc(d.description)}</textarea></div><p class="muted">Source: ${esc(d.file)}</p>`}$('#detailType').onchange=renderDetails;$('#detailSelect').onchange=renderDetailEditor;$('#saveDetail').onclick=async()=>{try{const type=$('#detailType').value,key=$('#detailSelect').value;await call('save-detail',{type,key,title:$('#detailTitle').value,description:$('#detailDescription').value});state.details[type][key].title=$('#detailTitle').value;state.details[type][key].description=$('#detailDescription').value;message('Detail page saved successfully.')}catch(x){message(x.message,true)}};
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.tabContent').forEach(x=>x.classList.add('hidden'));t.classList.add('active');$('#'+t.dataset.tab).classList.remove('hidden')});$('#logout').onclick=async()=>{await call('logout');location.reload()};init();
<?php endif; ?>
</script>
</body></html>
